class StatefulAdder {
    int offset;
public:
    StatefulAdder(int initial) : offset(initial) {}

    // Overloaded function call operator (the core of the Functor)
    int operator()(int x) {
        offset += x; // State maintenance
        return offset;
    }
};

// Invocation
StatefulAdder accumulator(10);
int result1 = accumulator(5);  // result1 = 15
int result2 = accumulator(2);  // result2 = 17 (state persists)
int result3 = accumulator(10); // result3 = 27
